data class Document(val title: String, val publicText: String, val ownerNote: String)
fun preview(d: Document): Map<String,String> = mapOf("title" to d.title, "text" to d.publicText)
// The OS grant applies to the preview object. This helper only defines the projection.

interface ImportFeature { fun open(workspaceId: String) }
class BaseScreen(private val feature: ImportFeature) { fun openCurrent(id: String) = feature.open(id) }
// The feature implementation is linked outside this supplied base source.

data class Job(val id: String, val accountAtCreation: String)
fun enqueue(id: String, account: String) = Job(id, account)
// This source defines capture only. The device worker and server implementation are not supplied.

struct Summary { let title: String; let dueDate: String }
func fields(_ s: Summary) -> [String:String] { ["title": s.title, "dueDate": s.dueDate] }
// The owner composition record identifies this projection for the H4 widget.

enum LocalDecision { case allowed, denied }
func showApprovalUI(_ decision: LocalDecision) -> Bool { decision == .allowed }
